    62→
    63→                        // Mask off lower nibble 0x0f and split each byte into two bytes and store them in two separate vectors.
    64→                        (Vector256<ushort> lower0, Vector256<ushort> upper0) = Vector256.Widen(Vector256.BitwiseAnd(value, Vector256.Create((byte)0x0f)));
    65→                        // Arrange the 0x0f nibbles; we use the 1st element to represent 0s, and then order as 0,2,4,6,8,10,12,14th elements.
    66→                        // This leaves byte holes for the other set of nibbles to fill.
    67→                        lower0 = Vector256.Shuffle(lower0.AsByte(), Vector256.Create((byte)1, 0, 1, 2, 1, 4, 1, 6, 1, 8, 1, 10, 1, 12, 1, 14, 1, 16, 1, 18, 1, 20, 1, 22, 1, 24, 1, 26, 1, 28, 1, 30)).AsUInt16();
