    70→                        // Mask off upper nibble 0xf0 and split each byte into two bytes and store them in two separate vectors.
    71→                        // Widening from byte -> ushort creates byte sized gaps so the two sets can be combined.
    72→                        (Vector256<ushort> lower1, Vector256<ushort> upper1) = Vector256.Widen(Vector256.BitwiseAnd(value, Vector256.Create((byte)0xf0)));
