      "code_excerpt": "// PRIMARY: src/Nethermind/Nethermind.Trie/HexPrefix.cs:CopyToSpan (lines 15-32)\npublic static void CopyToSpan(byte[] path, bool isLeaf, Span<byte> output)\n{\n    if (output.Length != ByteLength(path)) throw new ArgumentOutOfRangeException(nameof(output));\n    output[0] = (byte)(isLeaf ? 0x20 : 0x00);  // Leaf=0x20 (even), Extension=0x00 (even)\n    if (path.Length % 2 != 0)\n    {\n        output[0] += (byte)(0x10 + path[0]);  // Odd: Leaf=0x3X, Extension=0x1X\n    }\n    for (int i = 0; i < path.Length - 1; i += 2)\n    {\n        output[i / 2 + 1] =\n            path.Length % 2 == 0\n                ? (byte)(16 * path[i] + path[i + 1])\n                : (byte)(16 * path[i + 1] + path[i + 2]);\n    }\n}"
